import { Amplify } from "aws-amplify";
import "aws-amplify/auth/enable-oauth-listener";
import { listenForGoogleSignInFailures } from "./lib/googleSignIn";
// Generated by `npx ampx sandbox` locally or `ampx pipeline-deploy` in CI.
import outputs from "../amplify_outputs.json";

const migration = (outputs as unknown as { custom?: { migration?: { account?: string; appId?: string; branch?: string; preview?: string } } }).custom?.migration;
if (import.meta.env.VITE_HOA_MIGRATION_PREVIEW === "true" &&
  (migration?.account !== "917680434255" || migration.preview !== "true" || !migration.appId ||
    !["codex-hoa-account-migration", "codex-hoa-staging-migration"].includes(migration.branch ?? ""))) {
  throw new Error("The migration preview must use its isolated backend configuration.");
}
listenForGoogleSignInFailures();
Amplify.configure(outputs);
